<script setup lang="ts">
import {musicThemes} from "~/data/music"
const state=useAtelier(),audio=useAudio(),{t,language}=useLocale(),settings=ref(false)
const frameStats=useState('scene-performance',()=>({fps:0,renderMs:0,drawCalls:0,triangles:0,pixelRatio:0,visible:false}))
function toggleSound(){state.sound.value=!state.sound.value;audio.click()}
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{}}
</script>
<template>
 <header class="header"><NuxtLink to="/" class="wordmark">VELOCITY 3<span>AUTOMOBILI</span></NuxtLink><nav><NuxtLink to="/">{{t('Обзор','Experience')}}</NuxtLink><NuxtLink to="/garage">{{t('Гараж','Garage')}} <sup>08</sup></NuxtLink><NuxtLink :to="'/drive/'+state.car.value.id">{{t('В движении','In motion')}}</NuxtLink><NuxtLink to="/legal">{{t('Лицензии','Licenses')}}</NuxtLink></nav><div class="header-tools"><output class="live-fps" aria-live="off" aria-label="Текущий FPS">{{frameStats.visible?frameStats.fps:'—'}} <small>FPS</small></output><button class="language-button" :aria-label="language==='ru'?'Switch to English':'Перевести на русский'" @click="language=language==='ru'?'en':'ru'">{{language==='ru'?'EN':'RU'}}</button><button :aria-label="t('Настройки графики','Graphics settings')" @click="state.graphicsPrompt.value=!state.graphicsPrompt.value"><svg width="21" height="21" viewBox="0 0 24 24" fill="none" aria-hidden="true"><rect x="3" y="3" width="18" height="13" rx="2" stroke="currentColor" stroke-width="1.6"/><path d="M8 21h8M12 16v5M6 12l3-3 3 2 5-5" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg></button><button :aria-label="t('Настройки','Settings')" @click="settings=true">⚙</button><button :aria-label="t('Полный экран','Fullscreen')" @click="fullscreen">⛶</button></div></header>
 <aside v-if="state.graphicsPrompt.value" class="quick-graphics"><button class="dismiss-graphics" :aria-label="t('Закрыть настройки графики','Close graphics settings')" @click="state.graphicsPrompt.value=false">×</button><small>{{t('НАСТРОЙКИ ГРАФИКИ','GRAPHICS SETTINGS')}}</small><GraphicsControls /><button class="apply-graphics" @click="state.graphicsPrompt.value=false">{{t('Готово','Done')}} →</button></aside>
 <AtelierDialog v-if="settings" @close="settings=false"><small>VELOCITY 3 / {{t('ПАРАМЕТРЫ','PREFERENCES')}}</small><h2>{{t('Настройки','Settings')}}</h2><section class="music-picker" aria-label="Музыкальные темы"><div class="music-heading"><strong>{{t('Музыка · выбрать трек','Music · choose a track')}}</strong><label>{{t('Включена','Enabled')}}<input type="checkbox" v-model="state.music.value"></label></div><div class="music-tracks"><button v-for="theme in musicThemes" :key="theme.id" :aria-pressed="state.musicTheme.value===theme.id||(state.musicTheme.value==='auto'&&theme.id===(state.car.value.shape===0?'pulse':'atelier'))" @click="state.musicTheme.value=theme.id;state.music.value=true"><span>♫</span><span class="track-label">{{theme.name}}<small>{{theme.genre}} · {{theme.artist}}</small></span><span class="track-check">✓</span></button></div><button class="music-auto" :aria-pressed="state.musicTheme.value==='auto'" @click="state.musicTheme.value='auto'">{{t('Подбирать тему по автомобилю','Match music to vehicle')}}</button><p class="music-credit">{{musicThemes.filter(theme=>theme.artist==='Scott Buckley').map(theme=>theme.name).join(', ')}} — <a href="https://www.scottbuckley.com.au/library/" target="_blank" rel="noopener">Scott Buckley</a> · <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a></p></section><section class="graphics-section"><h3>{{t('Настройки графики','Graphics settings')}}</h3><button class="apply-graphics" @click="settings=false;state.graphicsPrompt.value=true">{{t('Качество и ограничение FPS','Quality and FPS limit')}} →</button></section><label>{{t('Тени','Shadows')}}<input type="checkbox" v-model="state.shadows.value"></label><label>{{t('Вращение света','Rotate lighting')}}<input type="checkbox" v-model="state.rotateLighting.value"></label><label>{{t('Анимация камеры','Camera animation')}}<input type="checkbox" v-model="state.motion.value"></label><label>{{t('Звуки интерфейса','Interface sounds')}}<input type="checkbox" v-model="state.sound.value" @change="audio.click()"></label><label>{{t('Громкость','Volume')}}<input type="range" min="0" max="1" step="0.01" v-model.number="state.volume.value" @change="audio.click()"></label><p>{{t('Музыка начинается после первого нажатия. Двигатель включается отдельно и звучит при движении. Качество графики меняет разрешение сцены и детализацию теней.','Music starts after your first interaction. Engine audio is enabled separately and plays while moving. Graphics quality changes render resolution and shadow detail.')}}</p></AtelierDialog>

<aside v-if="state.sceneReady.value&&!state.performanceHintDismissed.value" class="performance-tip" role="status"><button :aria-label="t('Закрыть предупреждение','Dismiss performance tip')" @click="state.performanceHintDismissed.value=true">×</button><strong>{{t('Для плавного просмотра','For a smooth experience')}}</strong><p>{{t('Если у вас слабый компьютер или низкий FPS и лаги, уменьшите качество графики и установите ограничение FPS в настройках графики.','If your computer is slow or you notice low FPS and stuttering, reduce graphics quality and set an FPS limit in Graphics settings.')}}</p><button class="tip-settings" @click="state.performanceHintDismissed.value=true;state.graphicsPrompt.value=true">{{t('Настройки графики','Graphics settings')}} →</button></aside></template>



